        name: result.name,
        pathDisplay: result.path_lower,
      };
    } catch (error) {
      throw new Error(`Failed to create shared link: ${(error as Error).message}`);
    }
  },
});

// ─── Default Export ─────────────────────────────────────────────────────────

export default {
